            for (let i = 0; i < hex.length; i += 2) out += String.fromCharCode(parseInt(hex.substr(i, 2), 16));
            for (const c of input) { if (c === "1") out = "\0" + out; else break; }
            return { result: out.replace(/^\0+/, ""), caption: "Decoded from Base58" };
          }
